WITH base AS (SELECT id, full_name, email, dept_id, manager_id, salary, hire_date, level, CASE WHEN is_remote THEN 'Yes' ELSE 'No' END AS is_remote_label, COALESCE(level, 'OTHER') AS resolved_level FROM employees WHERE hire_date > DATE '2023-02-13') SELECT level, APPROX_PERCENTILE(salary, ARRAY(0.25, 0.5, 0.75)) AS salary_quartiles, STDDEV_SAMP(salary) AS salary_stddev, SORT_ARRAY(COLLECT_SET(level)) AS level_list, COUNT(*) FILTER (WHERE level = 'L4') AS l4_rows, STDDEV_SAMP(salary) AS salary_stddev_2 FROM base GROUP BY level HAVING STDDEV_SAMP(salary) > 0
